contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run takes a candidate guess hash and an amount to send to lockInGuess
    function run(bytes32 guessHash, uint amount) public payable {
        require(address(this).balance >= amount);

        // First, read the current stored Guess for this address via the auto getter.
        // The getter for mapping(address => Guess) guesses returns (uint256, bytes32)
        (uint256 beforeBlock, bytes32 beforeHash) = c.guesses(address(this));

        // Attempt to call lockInGuess and capture whether it reverted.
        bool reverted;
        // call must be top-level statement
        try c.lockInGuess{value: amount}(guessHash) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read the stored Guess after the call
        (uint256 afterBlock, bytes32 afterHash) = c.guesses(address(this));

        // GENERAL RULE: If the call succeeded (did not revert) then:
        //  - exactly 1 ether must have been sent (amount == 1 ether),
        //  - there must have been no prior active guess (beforeBlock == 0),
        //  - the stored guess equals the provided guessHash,
        //  - the stored block number is nonzero and strictly greater than the current block number minus 1
        // If the call reverted then at least one of: amount != 1 ether or a prior guess existed (beforeBlock != 0).
        assert(
            (!reverted && amount == 1 ether && beforeBlock == 0 && afterHash == guessHash && afterBlock != 0)
            || (reverted && (amount != 1 ether || beforeBlock != 0))
        );
    }

    receive() external payable {}
}

