contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Params:
    // - guessHash: the hash to lock in
    // - lockValue: amount to send when calling lockInGuess (should be 1 ether to succeed)
    // - extra: a dummy uint to allow varied inputs (unused in logic)
    function run(bytes32 guessHash, uint lockValue, uint extra) public payable {
        require(address(this).balance >= lockValue + 0); // ensure we can fund lockInGuess

        // capture contract balance before any operations
        uint256 beforeC = address(c).balance;

        // Try to lock in a guess. It may revert (if already guessed or wrong value).
        bool lockReverted;
        try c.lockInGuess{value: lockValue}(guessHash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Now attempt to call settle(); it may revert or succeed.
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Observe after balance
        uint256 afterC = address(c).balance;

        // GENERAL RULE asserted:
        // If settle() did not revert then either:
        //  - before we had recorded a guess (i.e. lockInGuess succeeded) and the stored guess matched
        //    the computed answer at that stored block causing a payout of 2 ether (contract balance decreased by 2 ether),
        // OR
        //  - settle() succeeded but there was no payout (contract balance unchanged) — this can only happen if the guess did not match.
        // Because internal storage is not directly visible, we express the rule observationally:
        // If settle succeeded and the contract's balance decreased, it decreased by exactly 2 ether and lockInGuess must have succeeded earlier.
        assert(
            settleReverted
            || (
                // either no observable payout happened
                afterC == beforeC
            )
            || (
                // or an observable payout of exactly 2 ether occurred and lockInGuess previously succeeded
                (beforeC >= 2 ether && beforeC - afterC == 2 ether && !lockReverted)
            )
        );
    }

    // allow contract to receive ether so it can call lockInGuess
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that exercises settle() after optionally attempting lockInGuess
    // Params:
    // - tryLock: whether to attempt lockInGuess before calling settle
    // - lockValue: amount (in wei) to send when calling lockInGuess (should be 1 ether to succeed)
    // - guessHash: bytes32 passed to lockInGuess if tryLock is true
    function run(bool tryLock, uint lockValue, bytes32 guessHash) public payable {
        // allow any caller-provided funds; ensure we can forward lockValue if requested
        require(!tryLock || address(this).balance >= lockValue);

        // record balance before any interactions
        uint256 before = address(c).balance;

        // If requested, try to lock in a guess. This may revert; capture that fact.
        bool lockReverted = true;
        if (tryLock) {
            // ensure the call is a top-level statement that may revert; use try/catch to continue
            try c.lockInGuess{value: lockValue}(guessHash) {
                lockReverted = false;
            } catch {
                lockReverted = true;
            }
        }

        // Now call settle and record whether it reverted and balance after
        bool settleReverted;
        uint256 after;
        try c.settle() {
            settleReverted = false;
            after = address(c).balance;
        } catch {
            settleReverted = true;
            after = address(c).balance;
        }

        // GENERAL RULE (single assert):
        // If settle succeeded then the contract's balance did not increase; if it changed it decreased by exactly 2 ether.
        // If settle reverted there is no further guarantee here.
        assert(
            settleReverted
            || (
                // no increase
                after <= before
                && (
                    // either unchanged
                    after == before
                    // or decreased exactly 2 ether
                    || (before >= 2 ether && before - after == 2 ether)
                )
            )
        );
    }

    receive() external payable {}
}

