        } catch {
            lockedReverted = true;
        }

        // Read stored guess info after lock attempt
        (uint midBlock, bytes32 midGuess) = c.guesses(address(this));

        // Now attempt to advance blocks by making extraNoopCalls filler calls that do not modify guesses
        // We will call settle in a loop to consume blocks; settle may revert if conditions not met, so catch
        bool settledReverted = true;
        // perform extraNoopCalls no-op calls: calling a view via address(c).balance read isn't a transaction, so we use empty external calls to c that will revert; instead we use try/catch on settle to advance block number by issuing transactions
        for (uint i = 0; i < extraNoopCalls; i++) {
            try c.settle() {
                // if settle succeeds, then it cleared state and possibly paid out
            } catch {
                // ignore reverts; they still advance block
            }
        }

        // Now attempt to settle once and observe whether it reverts
        bool finalReverted;
        try c.settle() {
            finalReverted = false;
        } catch {
            finalReverted = true;
        }

        // Read contract balance and stored guess after settle attempt
        uint contractBalanceAfter = address(c).balance;
        (uint afterBlock, bytes32 afterGuess) = c.guesses(address(this));

        // The invariant we assert:
        // If settle succeeded (finalReverted == false) and the mid-state showed a stored guess equal to guessHash
        // then before the payout the contract must have had at least 2 ether (so transfer could succeed),
        // and after settle the stored block must be cleared (afterBlock == 0).
        // We cannot directly observe the contract balance "before" the transfer inside settle, but we can require
        // that if settle succeeded then contractBalanceAfter + 2 ether <= contractBalanceAfter_before which implies
        // contractBalanceAfter_before >= 2 ether. Since we cannot read the before value, we observe that the only way
        // settle succeeds and pays out is that it did not revert; thus we assert that when settle succeeded and the
        // midGuess matched, the stored guess is cleared afterwards and the current contract balance is <= the
        // previous balance (i.e., payout occurred) — but to keep the assertion purely observational and general,
        // we assert: if finalReverted == false and midGuess == guessHash then afterBlock == 0 and contractBalanceAfter <= address(this).balance + address(c).balance;

        // More directly and simply: If settle succeeded and midGuess matched, then afterBlock == 0 and contractBalanceAfter + 0 /*non-negative*/ <= address(c).balance + contractBalanceAfter (tautology).
        // To make a meaningful non-trivial assertion: If settle succeeded and midGuess == guessHash then afterBlock == 0.

        assert(!(finalReverted == false && midGuess == guessHash) || afterBlock == 0);
    }

