            // If either earlier call reverted, we don't attempt the second lock; mark as true to avoid forcing behavior.
            secondLockReverted = true;
        }

        // General rule: if both first lockInGuess and settle returned (did not revert), then the subsequent lockInGuess must be allowed (i.e., not revert).
