contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take parameters to drive lockInGuess and settle timing.
    // amount: amount to send when calling lockInGuess (should be 1 ether to succeed)
    // hash: the guess to lock
    // extra: an extra uint to decide whether to call settle before or after the target block
    function run(uint amount, bytes32 hash, uint extra) public payable {
        require(address(this).balance >= amount);
        // Ensure we start fresh: this test assumes it is the first caller using this address.
        // Call lockInGuess and capture whether it reverted.
        bool lockedReverted;
        try c.lockInGuess{value: amount}(hash) {
            lockedReverted = false;
        } catch {
            lockedReverted = true;
        }

        // Read observable state: mapping getter for this msg.sender (this contract)
        // The auto-generated getter for guesses returns (uint, bytes32)
        (uint lockedBlock, bytes32 storedGuess) = c.guesses(address(this));

        // Decide whether to call settle now or later based on extra bit
        bool settleReverted;
        // If lockedReverted then settle should revert if called because no guess was set
        // We attempt to call settle once; capture whether it reverts.
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Observables after calling settle: contract balance and stored block
        uint bal = address(c).balance;
        (uint afterBlock, bytes32 afterGuess) = c.guesses(address(this));

        // GENERAL ASSERTION (one assert):
        // - If lockInGuess reverted, then there must be no stored block (lockedBlock == 0) and settle must revert.
        // - If lockInGuess succeeded (lockedBlock != 0) then:
        //    * lockedBlock was set to a nonzero value.
        //    * settle may only succeed (not revert) when the stored block was nonzero; after a successful settle,
        //      the stored block must be reset to 0. If settle reverted, the stored block must remain unchanged.
        // These are properties observable via public getters and revert flags.
        assert(
            // case: lockInGuess reverted
            (lockedReverted && lockedBlock == 0 && settleReverted)
            ||
            // case: lockInGuess succeeded
            (!lockedReverted
                && lockedBlock != 0
                // if settle succeeded then afterBlock must be 0 (reset) and settleReverted==false
                && ((settleReverted == false && afterBlock == 0)
                    // if settle reverted then stored block should remain as before (no reset)
                    || (settleReverted == true && afterBlock == lockedBlock))
            )
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // amount: ether to send to lockInGuess (should be 1 ether to succeed)
    // hash: guess bytes32 to pass to lockInGuess
    function run(uint amount, bytes32 hash) public payable {
        // must have funds to forward to c when calling lockInGuess
        require(address(this).balance >= amount);

        // Try lockInGuess and record whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: amount}(hash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // Capture contract balance before settle to observe transfers
        uint balBefore = address(c).balance;

        // Try calling settle and record whether it reverted
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Capture contract balance after settle
        uint balAfter = address(c).balance;

        // Observations we can make via public surface:
        // - If lockInGuess reverted then this contract never sent 1 ether to c and c's balance should not have decreased because of a transfer to this.
        // - If lockInGuess succeeded then c had at least amount added at lock time; if settle succeeded it may transfer 2 ether back to this caller causing c's balance to decrease by 2 ether (if it had funds).
        // We cannot read the mapping directly; instead we assert the observable relation between reverts and balances:
        // General rule:
        // - If lockInGuess reverted then settle must revert (because no guess was stored for this caller). Observable consequence: when lockReverted is true, settleReverted must be true and balances unchanged (balBefore == balAfter).
        // - If lockInGuess succeeded then locked guess existed; after a successful settle (settleReverted == false) the contract balance cannot increase and may decrease by exactly 2 ether (if transfer happened). After a reverted settle the contract balance must remain the same as before settle.
        assert(
            // case: lockInGuess reverted -> settle reverted and no balance change
            (lockReverted && settleReverted && balBefore == balAfter)
            ||
            // case: lockInGuess succeeded -> settle reverted implies no balance change; settle succeeded implies balance did not increase (balAfter <= balBefore)
            (!lockReverted && (
                (settleReverted && balBefore == balAfter)
                ||
                (!settleReverted && balAfter <= balBefore)
            ))
        );
    }

    receive() external payable { }
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // amount must be provided to forward to lockInGuess; use 1 ether to try to succeed
    // hash is any bytes32 guess
    function run(uint amount, bytes32 hash) public payable {
        require(address(this).balance >= amount);

        // record contract balance before any calls
        uint balBeforeAll = address(c).balance;

        // Try lockInGuess and record whether it reverted
        bool lockReverted;
        try c.lockInGuess{value: amount}(hash) {
            lockReverted = false;
        } catch {
            lockReverted = true;
        }

        // After attempting lockInGuess, read observable: contract balance and guesses(msg.sender) via public getter
        uint balAfterLock = address(c).balance;
        // The automatically generated getter for guesses returns (uint, bytes32)
        (uint storedBlockAfterLock, bytes32 storedGuessAfterLock) = c.guesses(address(this));

        // Now attempt to call settle and record whether it reverted
        bool settleReverted;
        try c.settle() {
            settleReverted = false;
        } catch {
            settleReverted = true;
        }

        // Read after settle
        uint balAfterSettle = address(c).balance;
        (uint storedBlockAfterSettle, bytes32 storedGuessAfterSettle) = c.guesses(address(this));

        // General invariant to assert:
        // - If lockInGuess succeeded (lockReverted == false) then (A) it must have set storedBlockAfterLock != 0 and charged exactly 1 ether to the contract (balAfterLock == balBeforeAll + 1 ether).
        // - And after any non-reverting settle call (settleReverted == false) the stored block for this caller must be reset to 0 (storedBlockAfterSettle == 0).
        // - If lockInGuess reverted then the stored block must remain 0 and balances unchanged by that call.
        assert(
            (
                !lockReverted
                && storedBlockAfterLock != 0
                && balAfterLock == balBeforeAll + 1 ether
                && (
                    // if settle succeeded after a successful lock, the stored block must be cleared
                    (settleReverted || storedBlockAfterSettle == 0)
                )
            )
            ||
            (
                lockReverted
                && storedBlockAfterLock == 0
                && balAfterLock == balBeforeAll
                // if lock reverted then settle must revert (no guess stored) OR if settle did not revert it still must leave stored block 0
                && (settleReverted || storedBlockAfterSettle == 0)
            )
        );
    }

    receive() external payable { }
}
